ALTER TABLE public.shipper_subscriptions ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.subscription_payments ADD COLUMN recorded_by uuid, ADD COLUMN verified_at timestamptz;
CREATE TABLE public.app_settings(id text PRIMARY KEY,trip_otp_length integer NOT NULL DEFAULT 6,commission_rate numeric NOT NULL DEFAULT 0.05,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid);
GRANT SELECT,INSERT,UPDATE ON public.app_settings TO authenticated;
GRANT ALL ON public.app_settings TO service_role;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.app_settings FOR SELECT TO authenticated USING(true);
CREATE POLICY settings_admin ON public.app_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.ratings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES public.bookings(id),rater_id uuid NOT NULL,ratee_id uuid NOT NULL,rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),review text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(booking_id,rater_id));
GRANT SELECT,INSERT ON public.ratings TO authenticated;
GRANT ALL ON public.ratings TO service_role;
ALTER TABLE public.ratings ENABLE ROW LEVEL SECURITY;
CREATE POLICY ratings_read ON public.ratings FOR SELECT TO authenticated USING(rater_id=auth.uid() OR ratee_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.account_emails(id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,email text);
GRANT SELECT ON public.account_emails TO authenticated;
GRANT ALL ON public.account_emails TO service_role;
ALTER TABLE public.account_emails ENABLE ROW LEVEL SECURITY;
CREATE POLICY emails_admin ON public.account_emails FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
INSERT INTO public.account_emails(id,email) SELECT p.id,u.email FROM public.profiles p JOIN auth.users u ON u.id=p.id;
CREATE FUNCTION public.sync_account_email() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.account_emails(id,email) VALUES(NEW.id,NEW.email) ON CONFLICT(id) DO UPDATE SET email=EXCLUDED.email; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.sync_account_email() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER vahakam_sync_email AFTER INSERT OR UPDATE OF email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.sync_account_email();